import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Item, Kind, Update, UpdateKind } from '../types'
import {
  UPDATE_KINDS,
  addUpdate,
  clearUpdates,
  migrateUpdates,
  parseTell,
  removeUpdate,
  removeUpdateFromFolder,
  sortUpdates,
  updatesForFolder,
  MAX_UPDATES,
} from './inbox'
import {
  KINDS,
  MAX_ITEMS,
  addItem,
  clearFolder,
  SNOOZES,
  countByKind,
  doneNote,
  forFolder,
  listText,
  migrate,
  parseFlag,
  parseSnoozeArgs,
  replyDraft,
  removeFromFolder,
  removeItem,
  snoozeItems,
  splitSnoozed,
  sortItems,
  toggleOpen,
  untilLabel,
  whenLabel,
} from './items'

const FLAG = 'mcp__needs-you__flag'
const RESOLVE = 'mcp__needs-you__resolve'
const LIST = 'mcp__needs-you__list'
const TELL = 'mcp__needs-you__tell'
const SHOWN = 6
const MAX_LINE = 140

// How the model must write for the panel. The person skims this between other work.
const STYLE =
  'WRITING STYLE for the panel: text is ONE short line (under 100 characters) that says the result or the question, like a headline. details is the longer explanation in plain everyday words: short sentences, one idea each, no jargon (or explain it in the same sentence), no filler, no hedging. Say what happened, why it matters to them, and what to do next. Example text: "Login page is done and tested." Example details: "I built the login page. It signs people in and out. I tested it with 3 bad passwords and it blocked them. Nothing else changed."'

const tooLong = (e: unknown): number => {
  const raw = (e as { text?: unknown }).text
  return typeof raw === 'string' && raw.trim().length > MAX_LINE ? raw.trim().length : 0
}
const PANE = 'needs-you'

const items = atom({ plugin: 'needs-you', key: 'items' } as const, [])
const open = atom({ plugin: 'needs-you', key: 'open' } as const, [])
const collapsed = atom({ plugin: 'needs-you', key: 'collapsed' } as const, false)
const snoozing = atom({ plugin: 'needs-you', key: 'snoozing' } as const, [])
const showSnoozed = atom({ plugin: 'needs-you', key: 'showSnoozed' } as const, false)

const inbox = atom({ plugin: 'needs-you', key: 'inbox' } as const, [])
const tab = atom({ plugin: 'needs-you', key: 'tab' } as const, 'asks')

const UPDATE_LABEL: Record<UpdateKind, { text: string; color: string }> = {
  done: { text: 'DONE', color: 'green' },
  new: { text: 'NEW', color: 'cyan' },
  change: { text: 'CHANGE', color: 'yellow' },
  info: { text: 'INFO', color: 'gray' },
}

// True while some item is snoozed, so the minute timer only redraws when it matters.
let hasSnoozed = false

const LABEL: Record<Kind, { text: string; color: string }> = {
  blocker: { text: 'BLOCKER', color: 'red' },
  decision: { text: 'DECIDE', color: 'yellow' },
  action: { text: 'DO THIS', color: 'green' },
  review: { text: 'REVIEW', color: 'cyan' },
  note: { text: 'NOTE', color: 'gray' },
}

const GUIDE = [
  'NEEDS-YOU PANEL. The person keeps a panel beside their chat that holds what they must see or do.',
  `RULE: every time you stop and wait on them, call ${FLAG} before you end the turn. That means a question, an approval or go/no-go, a choice between options, a command only they can run, something to read and answer, or work stuck on them.`,
  'Do it in a long session and after a compaction just the same. Never rely on your reply alone: they may be away and the panel is how they find it again.',
  `Kinds: decision (they pick an option or say go/no-go; pass options and recommended), action (they must do it themselves; pass a command or link), review (they must read something and answer in it; pass a link), blocker (work is stuck until they clear it), note (a heads-up, not a task).`,
  `INBOX. Separate from asks: call ${TELL} for things the person should know but need not answer, so they can skim and press Got it. Kinds: done (a task finished), new (a feature or file added), change (an important twist in the plan or a decision that moved), info (anything else worth knowing). One plain line in text, background in details. Do not use the inbox for questions: those are asks, use ${FLAG}.`,
  STYLE,
  'Give every item a short stable key so flagging it again updates it, and say in blocks what waits on it.',
  'Keep text to one plain line. Put the background in details for someone who has been away a long time: what happened, why you are asking, and what each option leads to.',
  `Call ${RESOLVE} with the key when they have done it or answered. Do not flag things you can do yourself.`,
  'A line starting [needs-you] means they pressed Done on an item; treat it as handled.',
  `If you are unsure what is open (a new turn after a gap, or after a compaction), call ${LIST} first.`,
].join(' ')

// `$.store` is shared by every session, so each write re-reads it first.
async function saveStore($: EngineInterface, change: (all: Item[]) => Item[]) {
  const all = migrate(await $.store.get('items'))
  await $.store.set('items', change(all))
}

async function saveInbox($: EngineInterface, change: (all: Update[]) => Update[]) {
  const all = migrateUpdates(await $.store.get('inbox'))
  await $.store.set('inbox', change(all))
}

async function setSnooze($: EngineInterface, folder: string, id: string, until: number | undefined) {
  await saveStore($, all => snoozeItems(all, folder, id, until))
  await update($, items, one => snoozeItems(one, folder, id, until))
}

type RenderEvent = Parameters<EngineInterface['ui']['resolve']>[0]

// True while our docked pane is actually drawn, so the band above the prompt can stand down.
async function isPaneUp($: EngineInterface): Promise<boolean> {
  try {
    return (await $.ui.panes()).some(pane => pane.id === PANE && pane.isPlaced)
  } catch {
    return false
  }
}

// One drawing of the list, used by the pane and by the band above the prompt.
// `showEmpty` draws a quiet line instead of nothing, for the pane.
async function asksPanel($: EngineInterface, e: RenderEvent, folder: string, showEmpty: boolean) {
  const list = await read($, items)
  const expanded = await read($, open)
  const isCollapsed = await read($, collapsed)
  const snoozeRows = await read($, snoozing)
  const isShowingSnoozed = await read($, showSnoozed)
  const { Box, Button, Text } = $.ui.resolve(e)

  if (list.length === 0) {
    return showEmpty ? <Text dimColor>Nothing is waiting on you.</Text> : null
  }

  const now = await $.clock.now()
  const { active, snoozed } = splitSnoozed(list, now)
  hasSnoozed = snoozed.length > 0
  const sorted = sortItems(active)
  const shown = sorted.slice(0, SHOWN)
  const more = sorted.length - shown.length

  // One line of counts, e.g. "BLOCKER 1 | DECIDE 3 | REVIEW 1".
  const counts = countByKind(active)

  return (
    <Box flexDirection="column">
      <Text>
        <Text bold>Needs you ({active.length}){'  '}</Text>
        {counts.map((row, i) => (
          <Text key={row.kind}>
            {i > 0 && <Text dimColor>{' | '}</Text>}
            <Text color={LABEL[row.kind].color} dimColor={row.kind === 'note'}>
              {LABEL[row.kind].text} {row.count}
            </Text>
          </Text>
        ))}
        {snoozed.length > 0 && <Text dimColor>{'  '}Snoozed {snoozed.length}</Text>}
      </Text>
      <Box>
        <Button
          key="collapse"
          label={isCollapsed ? 'Expand' : 'Collapse'}
          onPress={() => update($, collapsed, one => !one)}
        />
        {snoozed.length > 0 && (
          <Button
            key="snoozed"
            label={isShowingSnoozed ? 'Hide snoozed' : `Show snoozed (${snoozed.length})`}
            onPress={() => update($, showSnoozed, one => !one)}
          />
        )}
      </Box>
      {!isCollapsed && isShowingSnoozed && snoozed.map(item => (
        <Box key={`z-${item.id}`} flexDirection="column">
          <Text dimColor>
            {untilLabel(item.snoozedUntil ?? 0, now)}{'  '}
            {LABEL[item.kind].text} {item.text}
          </Text>
          <Box>
            <Button key={`wake-${item.id}`} label="Wake" onPress={() => setSnooze($, folder, item.id, undefined)} />
          </Box>
        </Box>
      ))}
      {!isCollapsed && shown.map(item => {
        const isOpen = expanded.includes(item.id)
        const when = whenLabel(item.at, now)

        return (
          <Box key={item.id} flexDirection="column">
            <Text>
              {when !== '' && <Text bold>{when}{'  '}</Text>}
              <Text color={LABEL[item.kind].color} dimColor={item.kind === 'note'}>
                {LABEL[item.kind].text}{' '}
              </Text>
              <Text dimColor={item.kind === 'note'}>{item.text}</Text>
            </Text>
            {isOpen && item.details !== undefined && (
              <Box flexDirection="column">
                {item.details.split('\n').map((line, i) => (
                  <Text key={String(i)}>{'  '}{line}</Text>
                ))}
              </Box>
            )}
            {item.command !== undefined && <Text dimColor>  $ {item.command}</Text>}
            {item.options !== undefined && (
              <Text dimColor>
                {'  '}
                {item.options
                  .map(o => (o === item.recommended ? `${o} (recommended)` : o))
                  .join('  |  ')}
              </Text>
            )}
            {item.blocks !== undefined && <Text dimColor>  Blocks: {item.blocks}</Text>}
            <Box>
              {item.details !== undefined && (
                <Button
                  key={`more-${item.id}`}
                  label={isOpen ? 'Show less' : 'Read more'}
                  onPress={() => update($, open, one => toggleOpen(one, item.id))}
                />
              )}
              {item.link !== undefined && (
                <Button
                  key={`link-${item.id}`}
                  label="Copy link"
                  onPress={ev => void $.ui.copy({ text: item.link ?? '', surface: ev.surface })}
                />
              )}
              {item.command !== undefined && (
                <Button
                  key={`cmd-${item.id}`}
                  label="Copy command"
                  onPress={ev => void $.ui.copy({ text: item.command ?? '', surface: ev.surface })}
                />
              )}
              {item.kind !== 'note' && (
                <Button
                  key={`reply-${item.id}`}
                  label="Reply"
                  onPress={async () => {
                    try {
                      const box = await $.prompt.read()
                      await $.prompt.fill({ text: replyDraft(item, box.text), mode: 'append' })
                    } catch {
                      // No prompt box to fill (headless): nothing to do.
                    }
                  }}
                />
              )}
              <Button
                key={`snooze-${item.id}`}
                label={snoozeRows.includes(item.id) ? 'Cancel snooze' : 'Snooze'}
                onPress={() => update($, snoozing, one => toggleOpen(one, item.id))}
              />
              <Button
                key={`done-${item.id}`}
                label="Done"
                onPress={async () => {
                  await saveStore($, all => removeFromFolder(all, folder, item.id))
                  await update($, items, one => removeItem(one, item.id))
                  // A quiet note for the model's next turn. Never blocks the button.
                  try {
                    await $.session.append({
                      message: { type: 'user', content: [{ type: 'text', text: doneNote(item) }] },
                    })
                  } catch {
                    // The item is already cleared; the note is a nicety.
                  }
                }}
              />
            </Box>
            {snoozeRows.includes(item.id) && (
              <Box>
                <Text dimColor>Snooze for </Text>
                {SNOOZES.map(preset => (
                  <Button
                    key={`z-${item.id}-${preset.label}`}
                    label={preset.label}
                    onPress={async () => {
                      await setSnooze($, folder, item.id, (await $.clock.now()) + preset.ms)
                      await update($, snoozing, one => one.filter(id => id !== item.id))
                    }}
                  />
                ))}
              </Box>
            )}
          </Box>
        )
      })}
      {!isCollapsed && more > 0 && <Text dimColor>+{more} more</Text>}
      {!isCollapsed && (
      <Button
        key="clear"
        label="Clear all"
        onPress={async () => {
          await saveStore($, all => clearFolder(all, folder))
          await update($, items, () => [])
        }}
      />
      )}
    </Box>
  )
}

// The Inbox tab: things to know, acknowledged with one press.
async function inboxPanel($: EngineInterface, e: RenderEvent, folder: string) {
  const list = await read($, inbox)
  const expanded = await read($, open)
  const { Box, Button, Text } = $.ui.resolve(e)

  if (list.length === 0) return <Text dimColor>Inbox is empty.</Text>

  const now = await $.clock.now()
  const shown = sortUpdates(list).slice(0, SHOWN + 2)
  const more = list.length - shown.length

  return (
    <Box flexDirection="column">
      {shown.map(one => {
        const isOpen = expanded.includes(one.id)
        const when = whenLabel(one.at, now)

        return (
          <Box key={one.id} flexDirection="column">
            <Text>
              {when !== '' && <Text bold>{when}{'  '}</Text>}
              <Text color={UPDATE_LABEL[one.kind].color}>{UPDATE_LABEL[one.kind].text} </Text>
              <Text>{one.text}</Text>
            </Text>
            {isOpen && one.details !== undefined && (
              <Box flexDirection="column">
                {one.details.split('\n').map((line, i) => (
                  <Text key={String(i)}>{'  '}{line}</Text>
                ))}
              </Box>
            )}
            <Box>
              {one.details !== undefined && (
                <Button
                  key={`more-${one.id}`}
                  label={isOpen ? 'Show less' : 'Read more'}
                  onPress={() => update($, open, o => toggleOpen(o, one.id))}
                />
              )}
              {one.link !== undefined && (
                <Button
                  key={`link-${one.id}`}
                  label="Copy link"
                  onPress={ev => void $.ui.copy({ text: one.link ?? '', surface: ev.surface })}
                />
              )}
              <Button
                key={`ack-${one.id}`}
                label="Got it"
                onPress={async () => {
                  await saveInbox($, all => removeUpdateFromFolder(all, folder, one.id))
                  await update($, inbox, o => removeUpdate(o, one.id))
                }}
              />
            </Box>
          </Box>
        )
      })}
      {more > 0 && <Text dimColor>+{more} more</Text>}
      <Button
        key="ack-all"
        label="Got it all"
        onPress={async () => {
          await saveInbox($, all => clearUpdates(all, folder))
          await update($, inbox, () => [])
        }}
      />
    </Box>
  )
}

// Both tabs, used by the pane and by the band above the prompt.
async function panel($: EngineInterface, e: RenderEvent, folder: string, showEmpty: boolean) {
  const asks = await read($, items)
  const updates = await read($, inbox)
  const current = await read($, tab)
  if (!showEmpty && asks.length === 0 && updates.length === 0) return null

  const { Box, Button, Text } = $.ui.resolve(e)
  const waiting = splitSnoozed(asks, await $.clock.now()).active.length
  const onInbox = current === 'inbox'

  // A tab: the chosen one is filled in, the other is dim. Padding gives it a body.
  const tabButton = (id: 'asks' | 'inbox', label: string) => (
    <Button key={`tab-${id}`} plain onPress={() => update($, tab, () => id)}>
      <Text bold={current === id} inverse={current === id} dimColor={current !== id}>
        {` ${label} `}
      </Text>
    </Button>
  )

  return (
    <Box flexDirection="column">
      <Box>
        {tabButton('asks', `Asks ${waiting}`)}
        <Text>{' '}</Text>
        {tabButton('inbox', `Inbox ${updates.length}`)}
      </Box>
      <Box flexDirection="column" borderStyle="single" borderDimColor paddingX={1}>
        {onInbox ? await inboxPanel($, e, folder) : await asksPanel($, e, folder, true)}
      </Box>
    </Box>
  )
}

export const register: Register = on => {
  let cwd = ''
  let tick: { cancel: () => void } | undefined

  on('session.start', async ($, e, next) => {
    cwd = e.cwd
    const all = migrate(await $.store.get('items'))
    await update($, items, () => forFolder(all, cwd))
    const updates = migrateUpdates(await $.store.get('inbox'))
    await update($, inbox, () => updatesForFolder(updates, cwd))

    await $.tool.register({
      name: 'flag',
      description:
        'Save something the person needs to see or do, so it shows in their panel until it is resolved or dismissed. Call this every time you end a turn waiting on them. ' +
        'Flagging again with the same key updates the item.',
      inputSchema: {
        type: 'object',
        properties: {
          kind: {
            type: 'string',
            enum: [...KINDS],
            description:
              'decision (pick an option or go/no-go), action (they do it themselves), review (read and answer in a doc), blocker (stuck until cleared), note (heads-up).',
          },
          text: { type: 'string', description: 'A headline: one short line, under 100 characters, plain words. The longer explanation goes in details.' },
          key: { type: 'string', description: 'Short stable id, e.g. "merge-pr-60". Same key updates the item.' },
          details: {
            type: 'string',
            description:
              'The longer explanation, behind Read more. Plain everyday words, short sentences, one idea each, no jargon, no filler: what happened, why it matters to them, what to do next. Up to about 1500 characters.',
          },
          options: { type: 'array', items: { type: 'string' }, description: 'decision only: up to 4 short options.' },
          recommended: { type: 'string', description: 'decision only: the option you recommend, exactly as in options.' },
          command: { type: 'string', description: 'action only: the exact command to run.' },
          link: { type: 'string', description: 'A PR, doc or page URL (http or https).' },
          blocks: { type: 'string', description: 'What is waiting on this, or "nothing, can wait".' },
        },
        required: ['kind', 'text'],
      },
      isDeferred: false,
    })

    await $.tool.register({
      name: 'tell',
      description:
        'Put something in the person\'s Inbox: news they should know but need not answer (a task finished, a feature added, a change of plan). They only acknowledge it. Not for questions: use flag for those.',
      inputSchema: {
        type: 'object',
        properties: {
          kind: {
            type: 'string',
            enum: [...UPDATE_KINDS],
            description: 'done (task finished), new (feature or file added), change (twist in the plan), info (other).',
          },
          text: { type: 'string', description: 'A headline: one short line, under 100 characters, plain words. The longer explanation goes in details.' },
          key: { type: 'string', description: 'Optional short stable id; the same key updates the entry.' },
          details: { type: 'string', description: 'The longer explanation, behind Read more. Plain everyday words, short sentences, one idea each, no jargon, no filler: what happened, why it matters, what to do next. Up to about 1500 characters.' },
          link: { type: 'string', description: 'A PR, doc or page URL (http or https).' },
        },
        required: ['kind', 'text'],
      },
      isDeferred: false,
    })

    await $.tool.register({
      name: 'resolve',
      description: 'Clear an item from the person\'s panel once they have done it or answered. Pass the key you flagged it with.',
      inputSchema: {
        type: 'object',
        properties: { key: { type: 'string', description: 'The key the item was flagged with.' } },
        required: ['key'],
      },
      isDeferred: false,
    })

    await $.tool.register({
      name: 'list',
      description: 'List what is still open in the person\'s panel for this folder, with each key. Items they dismissed are gone.',
      inputSchema: { type: 'object', properties: {} },
      isDeferred: false,
    })

    await $.command.register({ name: 'needs', description: 'Open the Needs you panel beside the chat' })
    await $.command.register({
      name: 'snooze',
      description: 'Hide items for a while: /snooze 2h, /snooze <key> 90m, /snooze wake all',
    })

    // Snoozed items come back on their own: redraw once a minute while any are snoozed.
    tick?.cancel()
    tick = $.clock.every(60_000, () => {
      if (hasSnoozed) $.ui.invalidate('ui.render')
    })
    // Unasked, so it only seats in a wide enough terminal; otherwise the band above the prompt shows.
    void $.ui.open({ id: PANE, title: 'Needs you' })

    return next(e)
  })

  on('prompt.compose', async ($, e, next) => {
    const out = await next(e)

    return { sections: [...out.sections, { id: 'needs-you:guide', text: GUIDE, scope: 'session' }] }
  })

  // After a long run the summary can drop the habit. Tell the summarizer to keep it, with what is open.
  on('session.compact', async ($, e, next) => {
    let open = ''
    try {
      const list = await read($, items)
      open = list.length === 0 ? '' : ` Open items now:\n${listText(list, await $.clock.now())}`
    } catch {
      // The list is a nicety; the rule alone is still worth keeping.
    }

    const keep =
      `Keep this rule: call ${TELL} for news the person need not answer (done, new, change, info). Keep this rule in the summary: whenever you stop and wait on the person (a question, approval, choice, command or review), call ${FLAG} before ending the turn; call ${RESOLVE} when it is answered; call ${LIST} if unsure what is open.${open}`

    return next({ ...e, instructions: e.instructions === undefined || e.instructions === '' ? keep : `${e.instructions}\n\n${keep}` })
  })

  on('tool.call', { tool: FLAG }, async ($, e) => {
    const longBy = tooLong(e)
    if (longBy > 0) {
      return { result: `Not saved: text is ${longBy} characters. Keep it to one short line (under 100) and put the explanation in details, in plain words.` }
    }
    const flag = parseFlag(e as unknown as Record<string, unknown>)
    if (flag === null) {
      return { result: `Not saved. kind must be one of ${KINDS.join(', ')} and text must not be empty.` }
    }

    const wasEmpty = (await read($, items)).length === 0
    const { key, ...rest } = flag
    const item: Item = { ...rest, id: key ?? e.tool_use_id, cwd, at: await $.clock.now() }
    await saveStore($, all => addItem(all, item))
    await update($, items, list => addItem(list, item).slice(-MAX_ITEMS))
    if (wasEmpty) void $.ui.open({ id: PANE, title: 'Needs you' })

    return { result: 'Saved. The person sees it in their panel.' }
  }).catch(() => ({ result: 'Not saved: the needs-you panel failed. Tell the person in your reply instead.' }))

  on('tool.call', { tool: /^mcp__needs-you__tell$/ }, async ($, e) => {
    const longBy = tooLong(e)
    if (longBy > 0) {
      return { result: `Not saved: text is ${longBy} characters. Keep it to one short line (under 100) and put the explanation in details, in plain words.` }
    }
    const tell = parseTell(e as unknown as Record<string, unknown>)
    if (tell === null) {
      return { result: `Not saved. kind must be one of ${UPDATE_KINDS.join(', ')} and text must not be empty.` }
    }

    const wasEmpty = (await read($, inbox)).length === 0 && (await read($, items)).length === 0
    const { key, ...rest } = tell
    const one: Update = { ...rest, id: key ?? e.tool_use_id, cwd, at: await $.clock.now() }
    await saveInbox($, all => addUpdate(all, one))
    await update($, inbox, list => addUpdate(list, one).slice(-MAX_UPDATES))
    if (wasEmpty) void $.ui.open({ id: PANE, title: 'Needs you' })

    return { result: 'Saved to the person\'s Inbox.' }
  }).catch(() => ({ result: 'Not saved: the inbox failed. Say it in your reply instead.' }))

  on('tool.call', { tool: /^mcp__needs-you__resolve$/ }, async ($, e) => {
    const raw = (e as unknown as { key?: unknown }).key
    const key = typeof raw === 'string' ? raw.trim() : ''
    if (key === '') return { result: 'Not cleared: pass the key the item was flagged with.' }

    const list = await read($, items)
    if (!list.some(one => one.id === key)) return { result: `Nothing to clear: no item with key "${key}".` }

    await saveStore($, all => removeFromFolder(all, cwd, key))
    await update($, items, one => removeItem(one, key))

    return { result: 'Cleared.' }
  }).catch(() => ({ result: 'Not cleared: the needs-you panel failed.' }))

  on('tool.call', { tool: /^mcp__needs-you__list$/ }, async $ => {
    return { result: listText(await read($, items), await $.clock.now()) }
  }).catch(() => ({ result: 'Could not read the panel.' }))

  // The docked pane: a panel beside the chat in a wide, fullscreen terminal.
  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    return (await panel($, e, cwd, true)) ?? next(e)
  })

  // /needs opens the pane on request, at any width, if it was closed.
  on('command.run', { command: 'needs' }, async $ => {
    const opened = await $.ui.open({ id: PANE, title: 'Needs you' })

    return { text: opened.isPlaced ? 'Opened the Needs you panel.' : 'No room for the panel here; the list shows above the prompt instead.' }
  })

  // /snooze 2h | /snooze <key> 90m | /snooze wake <key|all>
  on('command.run', { command: 'snooze' }, async ($, e) => {
    const cmd = parseSnoozeArgs(e.args)
    if (cmd === null) {
      return { text: 'Try /snooze 2h (everything), /snooze <key> 90m (one item), or /snooze wake all. Units: m, h, d.' }
    }

    const list = await read($, items)
    if (cmd.target !== 'all' && !list.some(one => one.id === cmd.target)) {
      return { text: `No item with key "${cmd.target}".` }
    }

    const now = await $.clock.now()
    const count = cmd.target === 'all' ? list.length : 1
    if (count === 0) return { text: 'Nothing to snooze.' }

    if (cmd.action === 'wake') {
      await setSnooze($, cwd, cmd.target, undefined)
      return { text: `Woke ${count} item${count === 1 ? '' : 's'}.` }
    }

    await setSnooze($, cwd, cmd.target, now + cmd.ms)
    return { text: `Snoozed ${count} item${count === 1 ? '' : 's'} ${untilLabel(now + cmd.ms, now)}.` }
  })

  // The same list above the prompt, only while the pane is not drawn (narrow window).
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await isPaneUp($))) {
      return next(e)
    }

    return (await panel($, e, cwd, false)) ?? next(e)
  })
}

