import type { Update, UpdateKind } from '../types'

export const UPDATE_KINDS: readonly UpdateKind[] = ['done', 'new', 'change', 'info']
export const MAX_UPDATES = 200
const MAX_TEXT = 300
const MAX_DETAILS = 1500

const clean = (value: unknown, max = MAX_TEXT): string =>
  typeof value === 'string' ? value.trim().slice(0, max) : ''

export type Tell = { kind: UpdateKind; text: string; details?: string; link?: string; key?: string }

// Reads the model's tool input. Returns null when it is not a valid update.
export const parseTell = (input: Record<string, unknown>): Tell | null => {
  const kind = UPDATE_KINDS.find(k => k === input.kind)
  const text = clean(input.text)
  if (kind === undefined || text === '') return null

  const tell: Tell = { kind, text }
  const key = clean(input.key, 80)
  if (key !== '') tell.key = key
  const details = clean(input.details, MAX_DETAILS)
  if (details !== '') tell.details = details
  const link = clean(input.link, 500)
  if (/^https?:\/\/\S+$/.test(link)) tell.link = link

  return tell
}

// Same folder + same key (or same kind and text) updates in place.
export const addUpdate = (all: readonly Update[], one: Update): Update[] =>
  [...all.filter(u => !(u.cwd === one.cwd && (u.id === one.id || (u.kind === one.kind && u.text === one.text)))), one].slice(
    -MAX_UPDATES,
  )

export const removeUpdate = (all: readonly Update[], id: string): Update[] => all.filter(u => u.id !== id)

export const removeUpdateFromFolder = (all: readonly Update[], cwd: string, id: string): Update[] =>
  all.filter(u => !(u.cwd === cwd && u.id === id))

export const clearUpdates = (all: readonly Update[], cwd: string): Update[] => all.filter(u => u.cwd !== cwd)

export const updatesForFolder = (all: readonly Update[], cwd: string): Update[] => all.filter(u => u.cwd === cwd)

// Newest first.
export const sortUpdates = (list: readonly Update[]): Update[] => [...list].sort((a, b) => b.at - a.at)

export const migrateUpdates = (raw: unknown): Update[] =>
  Array.isArray(raw)
    ? raw.filter(
        (u): u is Update =>
          typeof u === 'object' && u !== null && UPDATE_KINDS.some(k => k === (u as { kind?: unknown }).kind),
      )
    : []

