import type { Item, Kind } from '../types'

export const KINDS: readonly Kind[] = ['decision', 'action', 'review', 'blocker', 'note']
export const MAX_ITEMS = 200
const MAX_TEXT = 300
const MAX_DETAILS = 1500
const MAX_OPTION = 80
const MAX_OPTIONS = 4

// Order of kinds in the summary line: things that stop work first, quiet notes last.
const RANK: Record<Kind, number> = { blocker: 0, decision: 1, action: 2, review: 3, note: 4 }

// Items saved by version 0.1 used other kind names.
const LEGACY: Record<string, Kind> = { run: 'action', suggestion: 'decision', input: 'decision' }

export type Flag = {
  kind: Kind
  text: string
  details?: string
  key?: string
  command?: string
  link?: string
  blocks?: string
  options?: string[]
  recommended?: string
}

const clean = (value: unknown, max = MAX_TEXT): string =>
  typeof value === 'string' ? value.trim().slice(0, max) : ''

export const normalizeKind = (value: unknown): Kind | undefined =>
  KINDS.find(k => k === value) ?? (typeof value === 'string' ? LEGACY[value] : undefined)

// Reads the model's tool input. Returns null when it is not a valid flag.
export const parseFlag = (input: Record<string, unknown>): Flag | null => {
  const kind = KINDS.find(k => k === input.kind)
  const text = clean(input.text)
  if (kind === undefined || text === '') return null

  const flag: Flag = { kind, text }

  const key = clean(input.key, 80)
  if (key !== '') flag.key = key

  // Longer background for someone who has been away. Shown behind "Read more".
  const details = clean(input.details, MAX_DETAILS)
  if (details !== '') flag.details = details

  const command = clean(input.command)
  if (kind === 'action' && command !== '') flag.command = command

  // A link is only ever shown as text and copied, but still must look like one.
  const link = clean(input.link, 500)
  if (/^https?:\/\/\S+$/.test(link)) flag.link = link

  const blocks = clean(input.blocks, 120)
  if (blocks !== '') flag.blocks = blocks

  if (kind === 'decision' && Array.isArray(input.options)) {
    const options = input.options
      .map(o => clean(o, MAX_OPTION))
      .filter(o => o !== '')
      .slice(0, MAX_OPTIONS)
    if (options.length > 0) {
      flag.options = options
      const recommended = clean(input.recommended, MAX_OPTION)
      if (options.includes(recommended)) flag.recommended = recommended
    }
  }

  return flag
}

// Same folder + same key (or same kind and text when no key) updates in place.
export const addItem = (all: readonly Item[], item: Item): Item[] => {
  const same = (one: Item): boolean =>
    one.cwd === item.cwd && (one.id === item.id || (one.kind === item.kind && one.text === item.text))

  const rest = all.filter(one => !same(one))
  return [...rest, item].slice(-MAX_ITEMS)
}

export const removeItem = (all: readonly Item[], id: string): Item[] =>
  all.filter(one => one.id !== id)

export const removeFromFolder = (all: readonly Item[], cwd: string, id: string): Item[] =>
  all.filter(one => !(one.cwd === cwd && one.id === id))

export const clearFolder = (all: readonly Item[], cwd: string): Item[] =>
  all.filter(one => one.cwd !== cwd)

export const forFolder = (all: readonly Item[], cwd: string): Item[] =>
  all.filter(one => one.cwd === cwd)

// Newest first, so what just happened is at the top.
export const sortItems = (list: readonly Item[]): Item[] =>
  [...list].sort((a, b) => b.at - a.at)

// How many items of each kind, in panel order, skipping kinds with none.
export const countByKind = (list: readonly Item[]): { kind: Kind; count: number }[] =>
  [...KINDS]
    .sort((a, b) => RANK[a] - RANK[b])
    .map(kind => ({ kind, count: list.filter(one => one.kind === kind).length }))
    .filter(row => row.count > 0)

// Snooze presets for the buttons. "Tomorrow" is simply 24 hours from now.
export const SNOOZES: readonly { label: string; ms: number }[] = [
  { label: '1h', ms: 3_600_000 },
  { label: '4h', ms: 4 * 3_600_000 },
  { label: '8h', ms: 8 * 3_600_000 },
  { label: 'Tomorrow', ms: 24 * 3_600_000 },
]
const MAX_SNOOZE_MS = 30 * 24 * 3_600_000

export const isSnoozed = (item: Pick<Item, 'snoozedUntil'>, now: number): boolean =>
  item.snoozedUntil !== undefined && item.snoozedUntil > now

export const splitSnoozed = (list: readonly Item[], now: number): { active: Item[]; snoozed: Item[] } => ({
  active: list.filter(one => !isSnoozed(one, now)),
  snoozed: list.filter(one => isSnoozed(one, now)),
})

// Snoozes (or, with `until` undefined, wakes) one item in a folder, or every
// item there when `id` is 'all'.
export const snoozeItems = (all: readonly Item[], cwd: string, id: string, until: number | undefined): Item[] =>
  all.map(one => {
    if (one.cwd !== cwd || (id !== 'all' && one.id !== id)) return one
    const { snoozedUntil: _gone, ...rest } = one
    return until === undefined ? rest : { ...rest, snoozedUntil: until }
  })

// "90m", "2h", "1.5h", "1d"; a bare number is minutes. Null when not a duration.
export const parseDuration = (text: string): number | null => {
  const m = /^(\d+(?:\.\d+)?)\s*(m|min|mins|h|hr|hrs|d|day|days)?$/i.exec(text.trim())
  if (m === null) return null

  const unit = (m[2] ?? 'm').toLowerCase()
  const per = unit.startsWith('d') ? 86_400_000 : unit.startsWith('h') ? 3_600_000 : 60_000
  const ms = Math.round(Number(m[1]) * per)

  return ms >= 60_000 && ms <= MAX_SNOOZE_MS ? ms : null
}

export type SnoozeCommand =
  | { action: 'snooze'; target: string; ms: number }
  | { action: 'wake'; target: string }

// `/snooze 2h`, `/snooze merge-pr-60 90m`, `/snooze wake all`. Null when unclear.
export const parseSnoozeArgs = (args: string): SnoozeCommand | null => {
  const words = args.trim().split(/\s+/).filter(w => w !== '')

  if (words[0]?.toLowerCase() === 'wake' && words.length === 2) {
    return { action: 'wake', target: words[1] ?? 'all' }
  }
  if (words.length === 1) {
    const ms = parseDuration(words[0] ?? '')
    return ms === null ? null : { action: 'snooze', target: 'all', ms }
  }
  if (words.length === 2) {
    const ms = parseDuration(words[1] ?? '')
    return ms === null ? null : { action: 'snooze', target: words[0] ?? 'all', ms }
  }

  return null
}

// "until 18:05" today, "until Wed 09:00" another day.
export const untilLabel = (until: number, now: number): string => {
  const d = new Date(until)
  if (Number.isNaN(d.getTime())) return ''
  const pad = (n: number) => String(n).padStart(2, '0')
  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
  const same = d.toDateString() === new Date(now).toDateString()

  return `until ${same ? '' : `${days[d.getDay()]} `}${pad(d.getHours())}:${pad(d.getMinutes())}`
}

// Brings items saved by older versions up to the current shape.
export const migrate = (raw: unknown): Item[] => {
  if (!Array.isArray(raw)) return []

  return raw.flatMap((one): Item[] => {
    const kind = normalizeKind((one as { kind?: unknown } | null)?.kind)
    if (kind === undefined) return []
    return [{ ...(one as Item), kind }]
  })
}

// The one line added to the session when the person presses Done. Keeps the
// model's own words out of the note beyond a short, capped copy.
export const doneNote = (item: Pick<Item, 'id' | 'kind' | 'text'>): string =>
  `[needs-you] The person marked this item done: ${item.kind} "${item.text.slice(0, 160)}" (key ${item.id}). ` +
  'No reply needed. Do not list it as waiting any more.'

// What the list tool returns to the model.
export const listText = (list: readonly Item[], now = 0): string => {
  if (list.length === 0) return 'The panel is empty: nothing is waiting on the person.'

  return sortItems(list)
    .map(
      one =>
        `- [${one.kind}] key ${one.id}: ${one.text}${one.blocks === undefined ? '' : ` (blocks: ${one.blocks})`}` +
        (isSnoozed(one, now) ? ` (snoozed ${untilLabel(one.snoozedUntil ?? 0, now)})` : ''),
    )
    .join('\n')
}

// "14:05 (2h ago)" for today, "Mon 14:05 (2d ago)" within a week, "3 Oct 14:05 (9d ago)"
// after that. Empty when the time cannot be formatted.
export const whenLabel = (at: number, now: number): string => {
  const d = new Date(at)
  if (Number.isNaN(d.getTime())) return ''

  const pad = (n: number) => String(n).padStart(2, '0')
  const clock = `${pad(d.getHours())}:${pad(d.getMinutes())}`
  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
  const today = new Date(now)
  const sameDay = d.toDateString() === today.toDateString()
  const ageMs = Math.max(0, now - at)
  const mins = Math.floor(ageMs / 60000)
  const hours = Math.floor(mins / 60)
  const daysAgo = Math.floor(hours / 24)

  const age = mins < 1 ? 'just now' : mins < 60 ? `${mins}m ago` : hours < 24 ? `${hours}h ago` : `${daysAgo}d ago`
  const day = sameDay ? '' : daysAgo < 7 ? `${days[d.getDay()]} ` : `${d.getDate()} ${months[d.getMonth()]} `

  return `${day}${clock} (${age})`
}

export const toggleOpen = (open: readonly string[], id: string): string[] =>
  open.includes(id) ? open.filter(one => one !== id) : [...open, id]

// Text the Reply button puts in the prompt box. Keeps whatever was already
// typed and leaves the cursor line free for the answer.
export const replyDraft = (item: Pick<Item, 'id' | 'text'>, draft: string): string => {
  const lead = draft === '' ? '' : draft.endsWith('\n') ? '\n' : '\n\n'

  return `${lead}Re: ${item.text.slice(0, 160)} [${item.id}]\n`
}

